<script setup>
import { ref } from 'vue'
import { Head, router, useForm } from '@inertiajs/vue3'
import AdminLayout from '../../../Layouts/AdminLayout.vue'
import PageHeader from '../../../Components/Ui/PageHeader.vue'
import AccountingNav from '../../../Components/Accounting/AccountingNav.vue'
import AccountingPanel from '../../../Components/Accounting/AccountingPanel.vue'
import Pagination from '../../../Components/Ui/Pagination.vue'
import { useConfirm } from '../../../Composables/useConfirm'
import { localDateInput } from '../../../Utils/dateInput'
defineOptions({layout:AdminLayout})
const props=defineProps({periods:Object,fiscalYears:Array,urls:Object});const {ask}=useConfirm();const now=new Date();const first=localDateInput(new Date(now.getFullYear(),now.getMonth(),1));const last=localDateInput(new Date(now.getFullYear(),now.getMonth()+1,0))
const createForm=useForm({fiscal_year_id:'',name:'',starts_on:first,ends_on:last,notes:''});const editForm=useForm({fiscal_year_id:'',name:'',starts_on:'',ends_on:'',notes:''});const editingId=ref(null)
function edit(period){editingId.value=period.id;Object.assign(editForm,{fiscal_year_id:period.fiscalYearId||'',name:period.name,starts_on:period.startsOn,ends_on:period.endsOn,notes:period.notes||''})}
const saveEdit=(period)=>editForm.put(period.updateUrl,{preserveScroll:true,onSuccess:()=>editingId.value=null});const create=()=>createForm.post(props.urls.store,{preserveScroll:true,onSuccess:()=>{createForm.reset();createForm.starts_on=first;createForm.ends_on=last}})
async function action(period,type){const closing=type==='close';const yes=await ask({title:closing?'إقفال الشهر؟':'إعادة فتح الشهر؟',message:closing?'سيُمنع ترحيل أي قيد جديد داخل مدته بعد فحص الجاهزية، من دون إنشاء قيد أرباح أو خسائر شهري.':'ستعود الفترة لاستقبال القيود، مع بقاء سجل الفتح والإقفال محفوظاً.',confirmLabel:closing?'إقفال الشهر':'إعادة الفتح',danger:closing});if(yes)router.post(closing?period.closeUrl:period.reopenUrl,{}, {preserveScroll:true})}
async function remove(period){const yes=await ask({title:'حذف الشهر الفارغ؟',message:'لن يسمح النظام بالحذف إذا كان الشهر يحتوي قيوداً أو بيانات مرتبطة.',confirmLabel:'حذف',danger:true});if(yes)router.delete(period.destroyUrl,{preserveScroll:true})}
</script>
<template><Head title="الفترات الشهرية"/><PageHeader title="الفترات الشهرية" icon="bi-calendar3" subtitle="راجع الشهر واقفله من نفس الشاشة؛ الإقفال يمنع تعديل التاريخ المحاسبي بعد اعتماده"/><AccountingNav :urls="urls" active="periods"/>
<section class="period-layout"><AccountingPanel title="إضافة شهر" description="الأسرع أن تُنشئ السنة بشهورها تلقائياً، ثم تضيف الاستثناءات فقط." icon="bi-calendar-plus"><form class="create-form" @submit.prevent="create"><label><span>السنة المالية</span><select v-model="createForm.fiscal_year_id" class="form-select"><option value="">بدون ربط</option><option v-for="year in fiscalYears" :key="year.id" :value="year.id" :disabled="year.closed">{{year.name}}{{year.closed?' — مقفلة':''}}</option></select></label><label><span>اسم الشهر <small>اختياري</small></span><input v-model="createForm.name" class="form-control" placeholder="يُسمّى تلقائياً"></label><div><label><span>من</span><input v-model="createForm.starts_on" type="date" class="form-control" required></label><label><span>إلى</span><input v-model="createForm.ends_on" type="date" class="form-control" required></label></div><label><span>ملاحظات</span><textarea v-model="createForm.notes" rows="2" class="form-control"></textarea></label><button class="btn btn-primary" :disabled="createForm.processing"><i class="bi bi-plus-lg"></i> إضافة الشهر</button></form></AccountingPanel>
<main class="period-list"><article v-for="period in periods.data" :key="period.id" class="period-card" :class="{closed:period.closed}"><header><span class="state"><i class="bi" :class="period.closed?'bi-lock-fill':'bi-unlock-fill'"></i></span><div><span><strong>{{period.name}}</strong><em :class="period.closed?'closed':'open'">{{period.closed?'مقفل':'مفتوح'}}</em><em v-if="period.fiscalYearName">{{period.fiscalYearName}}</em><em v-else class="warn">غير مربوط بسنة</em></span><small><i class="bi bi-calendar-range"></i> {{period.startsOn}} — {{period.endsOn}}</small><p v-if="period.notes">{{period.notes}}</p></div><div class="readiness" :class="{ready:!period.closed&&!period.issueCount}"><strong v-if="period.closed">تم الإقفال</strong><strong v-else-if="!period.issueCount">جاهز للإقفال</strong><strong v-else>{{period.issueCount}} ملاحظة</strong><small v-if="period.closed&&period.closedAt">{{period.closedAt}}</small></div></header><details v-if="!period.closed&&period.issueCount" class="checks"><summary>فحص ما قبل الإقفال</summary><span v-for="(check,i) in period.checks.filter(c=>!c.ok)" :key="i"><i class="bi bi-exclamation-circle"></i>{{check.label}}</span></details><div class="card-actions"><button v-if="!period.closed" type="button" @click="edit(period)"><i class="bi bi-pencil"></i> تعديل</button><button v-if="!period.closed" type="button" class="delete" @click="remove(period)"><i class="bi bi-trash3"></i></button><span></span><button v-if="period.closed" type="button" class="reopen" @click="action(period,'reopen')"><i class="bi bi-unlock"></i> إعادة فتح</button><button v-else type="button" class="close" @click="action(period,'close')"><i class="bi bi-lock"></i> إقفال الشهر</button></div><form v-if="editingId===period.id" class="edit-form" @submit.prevent="saveEdit(period)"><label><span>الاسم</span><input v-model="editForm.name" class="form-control" required></label><label><span>السنة</span><select v-model="editForm.fiscal_year_id" class="form-select"><option value="">بدون ربط</option><option v-for="year in fiscalYears" :key="year.id" :value="year.id">{{year.name}}</option></select></label><label><span>من</span><input v-model="editForm.starts_on" type="date" class="form-control" required></label><label><span>إلى</span><input v-model="editForm.ends_on" type="date" class="form-control" required></label><label class="notes"><span>ملاحظات</span><input v-model="editForm.notes" class="form-control"></label><button class="btn btn-primary"><i class="bi bi-check2"></i> حفظ</button><button type="button" class="btn btn-light" @click="editingId=null">إلغاء</button></form></article><div v-if="!periods.data.length" class="empty"><i class="bi bi-calendar-x"></i><strong>لا توجد شهور محاسبية</strong><span>أنشئ سنة مالية مع شهورها أو أضف أول شهر.</span></div><Pagination :links="periods.links"/></main></section></template>
