n{flex:1}.card-actions button{padding:6px 9px;border:1px solid #dce5df;border-radius:8px;color:#536258;background:#fff;font-size:.61rem;font-weight:800}.card-actions .delete{color:#ad2c2c}.card-actions .close{color:#fff;border-color:#1f6b50;background:#1f6b50}.card-actions .reopen{color:#945600;border-color:#e1be7a}.edit-form{display:grid;grid-template-columns:1.2fr 1fr 1fr 1fr;align-items:end;gap:8px;padding:11px 14px;border-top:1px solid #e2e8e4;background:#f7faf8}.edit-form .notes{grid-column:1/4}.empty{display:grid;justify-items:center;gap:4px;padding:60px;border:1px dashed #cedbd2;border-radius:15px;color:#829087;background:#fff}.empty i{font-size:1.5rem}.empty strong{font-size:.75rem}.empty span{font-size:.63rem}@media(max-width:1000px){.period-layout{grid-template-columns:1fr}.period-layout>:first-child{position:static}.create-form{grid-template-columns:1fr 1fr}.create-form>div{grid-column:1/-1}.create-form button{align-self:end}}@media(max-width:650px){.create-form{grid-template-columns:1fr}.create-form>div{grid-column:auto}.period-card>header{grid-template-columns:auto 1fr}.readiness{grid-column:2;justify-items:start}.edit-form{grid-template-columns:1fr 1fr}.edit-form .notes{grid-column:1/-1}}</style>
